<?php require_once __DIR__.'/ui.php';use Srms\Application as App;use Srms\Registry;page_heading($title,'Keep property and account records accurate and connected.');?><section class="panel form-panel"><?php form_start('save');hidden('type',$type);hidden('id',$record['id']??'');foreach(Registry::FIELDS[$type] as $f){$value=$record[$f]??match($f){'status'=>'active','ratepayer_type'=>'individual','opened_on'=>today(),'is_active','is_visible_by_default'=>1,'display_order'=>0,'ratepayer_number'=>\Srms\Settings::number(strtoupper(substr($type,0,4))),default=>''};$label=ucwords(str_replace('_',' ',$f));$refs=['parcel_id'=>'parcels','account_number'=>'properties','primary_ratepayer_id'=>'ratepayers','spatial_layer_id'=>'spatial_layers'];if($f==='account_number'){echo '<label class="field"><span>Permanent Account number *</span><input name="account_number" required pattern="EDDT[0-9]{8}" maxlength="12" placeholder="EDDT03011010" value="'.e($value).'" '.($record?'readonly':'').' aria-describedby="account-help"><small id="account-help">EDDT + division (2 digits) + block (3 digits) + parcel (3 digits). Cannot be changed once issued.</small></label>';}elseif(isset($refs[$f]))field($f,$label,$value,'select',$f==='account_number',App::options($refs[$f]));elseif($f==='status')field($f,$label,$value,'select',true,['active'=>'Active','archived'=>'Archived','closed'=>'Closed']);elseif($f==='ratepayer_type')field($f,$label,$value,'select',true,['individual'=>'Individual','corporate'=>'Corporate']);elseif(in_array($f,['notes','land_description','boundary_geojson','description']))field($f,$label,$value,'textarea');elseif(in_array($f,['is_active','is_visible_by_default']))field($f,$label,$value,'select',true,['1'=>'Yes','0'=>'No']);elseif(in_array($f,['opened_on','closed_on']))field($f,$label,$value,'date',$f==='opened_on');else field($f,$label,$value,in_array($f,['latitude','longitude','plot_size','display_order'])?'number':($f==='email'?'email':'text'),in_array($f,['property_number','parcel_number','ratepayer_number','full_name','account_number','name','layer_type']));}submit('Save record');?></section><?php if($type==='parcels'):?><section class="panel form-panel"><h2>Boundary editor</h2><p>Click to add polygon corners. Finish the boundary to populate the GeoJSON field above. Existing coordinates are preserved until you finish a new polygon.</p><div id="boundary-map" class="map-editor" data-tiles="<?=e(\Srms\Settings::get('map_tiles'))?>"></div><div class="toolbar"><button type="button" class="button" id="finish-boundary">Finish polygon</button><button type="button" class="button" id="clear-boundary">Clear draft</button></div></section><script defer src="<?=e(config('base_url'))?>/assets/leaflet/leaflet.js"></script><script defer src="<?=e(config('base_url'))?>/assets/map.js"></script><?php endif?>
